h2><p>Order muncul di sini setelah pelanggan mengisi form pengiriman fisik.</p></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Penerima</th><th>Alamat</th><th>Kurir</th><th>Total / Ongkir</th><th>Status & Resi</th></tr></thead><tbody><?php if (!$shippingOrders): ?><tr><td class="empty" colspan="6"><i class="fa-solid fa-box-open"></i><br>Belum ada paket yang perlu dikirim.</td></tr><?php else: foreach ($shippingOrders as $shippingOrder): ?><tr><td><strong><?= $e($shippingOrder['order_code']) ?></strong><small><?= $e($shippingOrder['service_title']) ?></small><small><?= date('d M Y, H:i', strtotime($shippingOrder['created_at'])) ?></small></td><td><strong><?= $e($shippingOrder['shipping_name']) ?></strong><small><?= $e($shippingOrder['shipping_phone']) ?></small></td><td class="address"><?= nl2br($e($shippingOrder['shipping_address'])) ?><br><?= $e($shippingOrder['shipping_city']) ?>, <?= $e($shippingOrder['shipping_postal_code']) ?></td><td><?= $e($shippingOrder['shipping_courier']) ?></td><td><strong><?= formatRupiah($shippingOrder['total_price']) ?></strong><small>Ongkir <?= formatRupiah($shippingOrder['shipping_cost']) ?></small></td><td><span class="status <?= $e($shippingOrder['shipping_status'] ?? 'menunggu') ?>"><?= $e($shippingLabels[$shippingOrder['shipping_status'] ?? 'menunggu'] ?? 'Menunggu diproses') ?></span><form class="shipping-form" method="post"><input type="hidden" name="action" value="update_shipping"><input type="hidden" name="csrf" value="<?= $e(adminCsrf()) ?>"><input type="hidden" name="order_id" value="<?= (int) $shippingOrder['id'] ?>"><select name="shipping_status"><?php foreach ($shippingLabels as $key => $label): ?><option value="<?= $key ?>" <?= ($shippingOrder['shipping_status'] ?? 'menunggu') === $key ? 'selected' : '' ?>><?= $e($label) ?></option><?php endforeach; ?></select><input name="shipping_tracking" value="<?= $e($shippingOrder['shipping_tracking'] ?? '') ?>" placeholder="No. resi"><button class="btn small" title="Simpan"><i class="fa-solid fa-check"></i></button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></div></section></main></div></body></html>
